function monthsInRange(){const a=[];for(let m=from.slice(0,7);m<=to.slice(0,7)&&a.length<240;m=moveMonth(m,1))a.push(m);return a}
function rangeToolbar(){return '<div class="toolbar"><label>С <input type="date" id="range-from" value="'+from+'"></label><label>По <input type="date" id="range-to" value="'+to+'"></label>'+button('Выбранный месяц','range-month','','quiet')+button('Весь год','range-year','','quiet')+'</div>'}
function calendarScreen(){const first=new Date(month+'-01T12:00:00'),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(1-offset);const days=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);days.push([d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'))}const events=calendarEvents(state,days[0],days[41]);return head('Календарь денег','Доходы, покупки, платежи и сроки целей. Любую запись можно изменить.')+
 '<div class="toolbar">'+button('+ Событие','new-event')+button('+ План расхода','new-expense-plan','','quiet')+button('Аналитика периода','calendar-analysis','','quiet')+'</div>'+rangeToolbar()+'<div class="calendar">'+['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(d=>'<div class="weekday">'+d+'</div>').join('')+days.map(d=>{const ev=events.filter(e=>e.date===d);return '<div class="day '+(!inMonth(d,month)?'outside':'')+' '+(d===today()?'today':'')+'"><div class="day-head"><span>'+Number(d.slice(8))+'</span><button class="icon-btn" data-action="new-event" data-date="'+d+'" aria-label="Добавить событие '+d+'">+</button></div>'+ev.slice(0,3).map(e=>'<button class="cal-event '+esc(e.kind)+(e.planned?' planned':'')+'" data-action="calendar-edit" data-entity="'+esc(e.entity)+'" data-id="'+esc(e.recordId)+'" aria-label="'+esc(dateLabel(e.date)+' · '+(e.planned?'План':'Факт')+' · '+e.title+(e.amount?' · '+money(e.amount):''))+'" title="'+esc(e.title+(e.amount?' · '+money(e.amount):''))+'">'+esc(e.title)+'</button>').join('')+(ev.length>3?button('Ещё '+(ev.length-3),'day-events','data-date="'+d+'"','quiet'):'')+'</div>'}).join('')+'</div><div class="calendar-legend"><span><i></i>Доход</span><span><i class="clay"></i>Расход / покупка</span><span><i class="sand"></i>Цель / напоминание</span><span>Пунктир — план</span></div><section class="section panel"><div class="section-head"><h2>В этом месяце</h2><small>'+monthLabel(month)+'</small></div>'+(events.filter(e=>inMonth(e.date,month)).sort((a,b)=>a.date.localeCompare(b.date)).map(eventRow).join('')||empty('Нажмите + в нужном дне, чтобы добавить событие.','new-event'))+'</section>'}
function eventRow(e){return '<div class="list-row"><div class="row-text"><strong>'+esc(e.title)+'</strong><small>'+dateLabel(e.date)+' · '+(e.planned?'Запланировано':'Запись')+'</small></div><span class="row-amount">'+(e.amount?money(e.amount):'')+'</span>'+controls(e.entity,e.recordId)+'</div>'}

function options(values,selected,emptyLabel=''){return (emptyLabel?'<option value="">'+esc(emptyLabel)+'</option>':'')+values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return '<option value="'+esc(id)+'" '+(String(id)===String(selected)?'selected':'')+'>'+esc(label)+'</option>'}).join('')}
function field(label,name,value='',type='text',extra='',wide=false){return '<label class="field '+(wide?'wide':'')+'">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>'}
function select(label,name,values,selected,emptyLabel='',wide=false,extra=''){return '<label class="field '+(wide?'wide':'')+'">'+label+'<select name="'+name+'" '+extra+'>'+options(values,selected,emptyLabel)+'</select></label>'}
