  if(entity==='operations')record={...record,kind:v.kind,amount:parseMoney(v.amount),date:v.date,category:(v.category||'').trim(),sourceId:null,accountId:v.accountId||null,toAccountId:v.kind==='transfer'?(v.toAccountId||null):null,title:v.title.trim()};
  if(entity==='accounts')record={...record,name:accountName(state,v.bank,v.type,newId),type:v.type,bank:v.bank.trim(),balance:parseMoney(v.balance),date:v.date,share:Number(v.share??100)};
  if(entity==='sources')record={...record,name:v.name.trim(),category:v.category.trim()};
  if(entity==='expensePlans')record=expensePlanRecord(v,newId);
  if(entity==='goals')record={...record,title:v.title.trim(),period:v.period,periodKey:v.period==='month'?v.periodMonth:v.periodYear,target:parseMoney(v.target),dueDate:v.dueDate||null,accountId:v.accountId||null};
