  if(entity==='notes')record={...record,date:v.date,month:v.month,title:v.title.trim(),text:v.text.trim()};
  if(entity==='snapshots')record={...record,month:v.month,date:v.date,note:v.note.trim(),income:r.income,expense:r.expense,planIncome:r.planIncome,planExpense:r.planExpense};
  if(entity==='events')record={...record,date:v.date,title:v.title.trim(),kind:v.kind,amount:v.amount.trim()?parseMoney(v.amount):null,notes:v.notes.trim()};
